export const meta = {
  name: 'intent-pipeline-runs',
  description: 'Run 5 draft intent pipelines on 2 captcha questions with a simulated operator (15 runs)',
  phases: [{ title: 'Runs' }],
}
const ROOT = 'C:/Users/alder/Desktop/Harness seed/.claude/worktrees/brainstorming-intent-pipelines'
const EXP = 'System/Brainstorms/Experiments/2026-10-15'
const PROTO = { P1: 'P1_lens_cards.md', P2: 'P2_draft_and_claims.md', P3: 'P3_best_worst.md', P4: 'P4_decision_forks.md', P5: 'P5_hybrid.md' }
const CAP = { P1: 5, P2: 5, P3: 6, P4: 4, P5: 5 }
const RUNNER = {
  type: 'object',
  properties: {
    round_folder: { type: 'string', description: 'run-relative path of the round folder just written, e.g. Round_02' },
    kind: { type: 'string', enum: ['expand', 'intent', 'none'] },
    operator_files: { type: 'array', items: { type: 'string' }, description: 'run-relative paths of files the operator must read and tick this round' },
    gate_ok: { type: 'boolean', description: 'false if the previous round was not fully ticked' },
    note: { type: 'string' },
  },
  required: ['round_folder', 'kind', 'operator_files', 'gate_ok', 'note'],
}
const SIM = {
  type: 'object',
  properties: {
    ticks: { type: 'number' },
    note_words: { type: 'number' },
    intent_verdict: { type: 'string', enum: ['yes', 'close', 'no', 'not_an_intent_round'] },
  },
  required: ['ticks', 'note_words', 'intent_verdict'],
}
const runnerPrompt = (run, i) => `You are running one round of a draft intent-clarification pipeline in the harness at ${ROOT} (a git worktree; work only inside it).

Run folder: ${ROOT}/${EXP}/runs/${run.id}/
Pipeline protocol: ${ROOT}/System/Brainstorms/Pipelines/${PROTO[run.p]}${run.p === 'P1' ? ' (it points to .claude/skills/expand-question/SKILL.md and Knowledge/Questions/TEMPLATE_CARD.md; read both)' : ''}
Shared contract: ${ROOT}/System/Brainstorms/Pipelines/CONTRACT.md
Research brief (use it instead of doing your own research; at most 2 extra web searches if something material is missing): ${ROOT}/${EXP}/research_${run.q}.md
Operator's voice: read 2-3 files in ${ROOT}/System/Snippets/ only if you are writing an INTENT.md.

This is interaction ${i} of at most ${CAP[run.p]}. Read the protocol, the contract, and everything already in the run folder (earlier rounds with their ticks, notes fences and SIMULATED.md logs). Then do exactly one step:
- If no round exists: write Round_01 per the protocol.
- If the latest round is not fully ticked per its gate: write nothing, return gate_ok=false.
- If the protocol's stop rule fires, or this is interaction ${CAP[run.p]}: write the next round folder containing INTENT.md in the contract format (an INTENT round), built from everything rated and noted so far.
- If the latest round folder holds an INTENT.md ticked "Close" or "No": per the protocol, write the follow-up round (or, if this is the last interaction, a revised INTENT round).
- Otherwise write the next round per the protocol.
Every round folder gets a ROUND.md with your reasoning notes. Number round folders Round_01, Round_02, ...

Rules: never tick a box; never answer the captcha question itself; never read anything under C:/Users/alder/.claude/jobs/; do not run git; do not write outside the run folder. Return the round folder you wrote, its kind, and the operator-facing files in it (not ROUND.md).`
const simPrompt = (run, r, key) => `You are simulating the operator for an experiment in ${ROOT}. Persona and mode rules: ${ROOT}/${EXP}/OPERATOR_PERSONA.md. Your mode: ${run.mode}.

The operator's real intent (hidden from the pipeline; you know it because you ARE him):
--- voice ---
${key.voice}
--- structured ---
${key.structured}
--- ideas he would welcome if shown ---
${key.would_value.map(s => '- ' + s).join('\n')}

Round to answer: ${ROOT}/${EXP}/runs/${run.id}/${r.round_folder}/. Operator-facing files: ${r.operator_files.join(', ')}.
Do not read ROUND.md or any other run folder. Read each operator-facing file once, as the persona would, then edit it in place: tick boxes by changing "- [ ]" to "- [x]" exactly as the file's instructions ask, and write in its notes fence only as the mode allows (his style: short, lower case, direct; never paste the hidden intent wholesale; reveal only what he would naturally say in reaction to what is on the page). Rate ideas you were not expecting by whether they serve what he actually wants.
Then append to ${r.round_folder}/SIMULATED.md one line per file listing what you ticked, under a header line: "Simulated operator (Sonnet 5.5, mode ${run.mode}). Not the operator's input."
Return the number of boxes you ticked, the words you wrote in notes, and, if the round holds INTENT.md, your verdict on it (else not_an_intent_round).`

phase('Runs')
const results = await pipeline(args.runs, async (run) => {
  const key = args.key[run.q.toLowerCase()]
  const log_ = []
  for (let i = 1; i <= CAP[run.p]; i++) {
    const r = await agent(runnerPrompt(run, i), { label: `${run.id} r${i}`, phase: 'Runs', effort: 'high', schema: RUNNER })
    if (!r) { log_.push({ i, error: 'runner null' }); break }
    if (!r.gate_ok || r.kind === 'none') { log_.push({ i, runner: r }); break }
    const s = await agent(simPrompt(run, r, key), { label: `${run.id} sim${i}`, phase: 'Runs', model: 'sonnet', effort: 'medium', schema: SIM })
    log_.push({ i, runner: r, sim: s })
    if (s && r.kind === 'intent' && s.intent_verdict === 'yes') break
  }
  return { id: run.id, rounds: log_ }
})
return results

