import os, re, sys

LABEL = "> Ticks and notes in this file are SIMULATED (Sonnet 5.5 playing the operator), not the operator's input.\n\n"
runs_dir = sys.argv[1]
n = 0
for root, _, files in os.walk(runs_dir):
    if not os.path.basename(root).startswith("Round_"):
        continue
    for f in files:
        if not f.endswith(".md") or f in ("ROUND.md", "SIMULATED.md"):
