"""Rough estimate of a session's context size from its transcript (main thread only, chars/4)."""
import json, sys

chars = 0
last_compact = 0
lines = open(sys.argv[1], encoding="utf-8").read().splitlines()
for i, line in enumerate(lines):
    try:
        o = json.loads(line)
    except Exception:
        continue
    if o.get("isSidechain"):
        continue
    if o.get("type") == "system" and "compact" in str(o.get("subtype", "")):
        last_compact = i
for line in lines[last_compact:]:
    try:
        o = json.loads(line)
    except Exception:
        continue
    if o.get("isSidechain") or o.get("type") not in ("user", "assistant"):
        continue
    c = o.get("message", {}).get("content")
    chars += len(json.dumps(c, ensure_ascii=False)) if not isinstance(c, str) else len(c)
print(f"~{chars // 4:,} tokens since last compaction (chars/4 estimate)")

