export const meta = {
  name: 'pmf-design',
  description: 'PMF tester phase 2: three independent architectures, adversarial judge panel, DESIGN.md with module contracts',
  phases: [{ title: 'Propose' }, { title: 'Judge' }, { title: 'Synthesize' }],
}
const ROOT = 'C:/Users/alder/Desktop/Harness seed/.claude/worktrees/brainstorming-intent-pipelines'
const PMF = ROOT + '/Work/PMF-tester'
const CONTEXT = `Spec: ${ROOT}/System/Snippets/SNIP_2026-10-15_014914.md (section 3) and SNIP_2026-10-15_015817.md. Build plan with hard safety limits: ${PMF}/BUILD_PLAN.md (read the limits and the phase-1 log line with the critic gaps). Research: ${PMF}/research/STEP_MAP.md and the step files beside it. Environment: Windows 11, Python 3.14 and Node 24 available, solo operator with low Operator RAM who runs Claude Code; no Docker assumed.`
const STACKS = [
  'Python package + CLI, SQLite state machine per idea, a small scheduler loop, adapters per vendor with dry-run mocks.',
  'TypeScript/Node package + CLI, file-based JSON state per idea (git-friendly), adapters per vendor with dry-run mocks.',
  'Minimal-build approach: adopt existing services wherever the research says they fit (e.g. a sending platform\'s own sequences and pre-warmed mailboxes, a hosted landing builder), and build only the thin orchestration, scoring and hand-off layer.',
]
const PROPOSAL = {
  type: 'object',
  properties: {
    name: { type: 'string' },
    design_markdown: { type: 'string', description: 'architecture: modules with responsibilities and interfaces, state model and lifecycle of an idea (states and transitions incl. operator hand-off states), adapter pattern with dry_run, scheduling over weeks, budget tracking, compliance gates, PMF scoring (Jev + fallback), test strategy, file layout' },
    covers_critic_gaps: { type: 'string' },
    risks: { type: 'array', items: { type: 'string' } },
  },
  required: ['name', 'design_markdown', 'covers_critic_gaps', 'risks'],
}
phase('Propose')
const props = (await parallel(STACKS.map((s, i) => () => agent(`Propose an architecture for the PMF tester baseline build. ${CONTEXT}\n\nYour approach: ${s}\nRequirements: every external side effect behind an adapter with dry_run=True default and a mock; operator hand-offs (captcha signups, KYC, billing, OAuth consent, reply handling) are first-class states shown to the operator in very short prompts; resumable over weeks; per-idea budget; compliance gates (EU sender, CZ blocked by default, suppression list, unsubscribe); idea -> ICP -> lead queries -> copy step included; testable fully offline. Be concrete enough that parallel agents can implement modules from your interfaces.`, { label: `propose:${i + 1}`, phase: 'Propose', effort: 'high', schema: PROPOSAL })))).filter(Boolean)
phase('Judge')
const SCORE = { type: 'object', properties: { scores: { type: 'array', items: { type: 'object', properties: { idx: { type: 'number' }, feasibility_tonight: { type: 'number' }, safety_limits: { type: 'number' }, operator_ram: { type: 'number' }, resumability: { type: 'number' }, testability: { type: 'number' }, total: { type: 'number' } }, required: ['idx', 'feasibility_tonight', 'safety_limits', 'operator_ram', 'resumability', 'testability', 'total'] } }, graft: { type: 'array', items: { type: 'string' } }, flaws: { type: 'array', items: { type: 'string' } } }, required: ['scores', 'graft', 'flaws'] }
const listing = props.map((p, i) => `### Proposal ${i}: ${p.name}\n${p.design_markdown}\n\nCritic gaps: ${p.covers_critic_gaps}\nRisks: ${p.risks.join('; ')}`).join('\n\n')
const judges = (await parallel(['inherit', 'fable'].map(m => () => agent(`Adversarially judge these architectures for the PMF tester baseline. ${CONTEXT}\n\nScore 0-10 each: feasibility_tonight (can parallel agents build a working offline dry-run in one night), safety_limits (impossible to cause a real side effect by accident), operator_ram (hand-offs and status are tiny to read), resumability, testability; total = sum. List the best ideas to graft and fatal flaws.\n\n${listing}`, { label: `judge:${m}`, phase: 'Judge', model: m === 'inherit' ? undefined : 'fable', effort: 'high', schema: SCORE })))).filter(Boolean)
const totals = props.map((_, i) => judges.reduce((s, j) => s + ((j.scores.find(x => x.idx === i) || {}).total || 0), 0))
log(`architecture totals: ${totals.join(', ')}`)
phase('Synthesize')
const MOD = { type: 'object', properties: { language: { type: 'string' }, test_command: { type: 'string' }, modules: { type: 'array', items: { type: 'object', properties: { key: { type: 'string' }, path: { type: 'string' }, spec: { type: 'string', description: 'what to build, interfaces it must expose and consume, tests it must have; self-contained enough for one agent' } }, required: ['key', 'path', 'spec'] } }, scaffold_note: { type: 'string' } }, required: ['language', 'test_command', 'modules', 'scaffold_note'] }
const out = await agent(`Write ${PMF}/DESIGN.md: the chosen architecture for the PMF tester baseline, taking the highest-scoring proposal (totals by index: ${JSON.stringify(totals)}) and grafting the judges' best ideas, fixing every fatal flaw. Sections: Overview; Idea lifecycle (states + transitions, hand-off states); Modules and interfaces; Adapters and dry-run guarantee; Compliance gates; PMF scoring; Scheduling and budget; File layout; Test strategy; Decisions taken without the operator (every guess about his intent, one line each, marked GUESS). Then create the scaffold in ${PMF}/ (package skeleton, shared types/interfaces, config with dry_run true, .env.example, test runner config) so module agents can work in parallel without touching each other's files. Return the module list for parallel implementation (8-14 modules, each with its own path that no other module writes) and the test command.\n\nProposals:\n${listing}\n\nJudges:\n${JSON.stringify(judges, null, 1)}`, { label: 'synthesize', phase: 'Synthesize', effort: 'high', schema: MOD })
return { totals, flaws: judges.flatMap(j => j.flaws), plan: out }

