  name: 'intent-pipeline-runs-B',
  description: 'Experiment B: P3, P5 (contract A) and P6, P7 (contract B) on both captcha questions, simulated operator holds the real intent',
  phases: [{ title: 'Runs' }],
}
const ROOT = 'C:/Users/alder/Desktop/Harness seed/.claude/worktrees/brainstorming-intent-pipelines'
const EXP = 'System/Brainstorms/Experiments/2026-10-15'
const PROTO = { P3: 'P3_best_worst.md', P5: 'P5_hybrid.md', P6: 'P6_tensions_and_claims.md', P7: 'P7_ticked_ledger.md' }
const CONTRACT = { P3: 'CONTRACT.md', P5: 'CONTRACT.md', P6: 'CONTRACT_B.md', P7: 'CONTRACT_B.md' }
const CAP = { P3: 6, P5: 5, P6: 5, P7: 5 }
const RUNNER = { type: 'object', properties: { round_folder: { type: 'string' }, kind: { type: 'string', enum: ['expand', 'intent', 'none'] }, operator_files: { type: 'array', items: { type: 'string' } }, gate_ok: { type: 'boolean' }, note: { type: 'string' } }, required: ['round_folder', 'kind', 'operator_files', 'gate_ok', 'note'] }
const SIM = { type: 'object', properties: { ticks: { type: 'number' }, note_words: { type: 'number' }, intent_verdict: { type: 'string', enum: ['yes', 'close', 'no', 'not_an_intent_round'] } }, required: ['ticks', 'note_words', 'intent_verdict'] }
const runnerPrompt = (run) => `You are running one round of a draft intent-clarification pipeline in the harness at ${ROOT} (a git worktree; work only inside it).

Run folder: ${ROOT}/${EXP}/runs_B/${run.id}/
Pipeline protocol: ${ROOT}/System/Brainstorms/Pipelines/${PROTO[run.p]}
Contract: ${ROOT}/System/Brainstorms/Pipelines/${CONTRACT[run.p]}
Research brief (use it instead of your own research; at most 2 extra web searches if something material is missing): ${ROOT}/${EXP}/research_${run.q}.md
Operator's voice: if you write an INTENT.md, read 2 of these snippets: ${ROOT}/System/Snippets/SNIP_2026-10-14_231927.md, SNIP_2026-10-15_001424.md, SNIP_2026-10-15_012022.md.
Forbidden to read (they would leak the answer): System/Snippets/SNIP_2026-10-15_014914.md, System/Snippets/SNIP_2026-10-15_015817.md, anything under Work/, anything under ${EXP}/runs/ or other runs_B folders, anything under C:/Users/alder/.claude/jobs/.

The run may already be part-way through. The round cap is ${CAP[run.p]} round folders. Read the protocol, the contract, and everything in the run folder (earlier rounds with ticks, notes and SIMULATED.md). Then do exactly one step:
- If no round exists: write Round_01 per the protocol.
- If the latest round has operator files without SIMULATED.md, or is not fully ticked per its gate: write nothing; return gate_ok=false, round_folder = that round, kind = its kind, operator_files = its operator-facing files.
- If the pipeline is finished (its final INTENT.md written and, if the contract has a Confirm block, ticked Yes), or ${CAP[run.p]} round folders exist and the last is fully handled: write nothing; return kind "none".
- If the protocol says the next step is the final INTENT.md with nothing for the operator to tick: write it (in the next round folder or the run root, as the protocol says) and return kind "intent" with operator_files empty.
- Otherwise write the next round per the protocol (or, if ${CAP[run.p] - 1} round folders exist, the final round the protocol prescribes).
Every round folder you write gets a short ROUND.md design log: bullets saying what the round contains and which ticks or notes led to each change. Number round folders Round_01, Round_02, ...
Rules: never tick a box; never answer the captcha question; do not run git; do not write outside the run folder.`
const simPrompt = (run, r) => `You are simulating the operator for an experiment in ${ROOT}. Persona and mode rules: ${ROOT}/${EXP}/OPERATOR_PERSONA.md. Your mode: ${run.mode}.

His real intent (hidden from the pipeline; you know it because you ARE him): read C:/Users/alder/.claude/jobs/fa864524/tmp/hidden/answer_key_real.json, the "${run.q.toLowerCase()}" entry (voice is his own words; elements and would_value were derived by the assistant).

Round to answer: ${ROOT}/${EXP}/runs_B/${run.id}/${r.round_folder}/. Operator-facing files: ${r.operator_files.join(', ')}.
Do not read ROUND.md or any other folder. Read each operator-facing file once, as the persona would, then edit it in place: tick boxes by changing "- [ ]" to "- [x]" exactly as the file asks, and write in its notes fence only as the mode allows (short, lower case, direct; never paste the hidden intent wholesale; react only to what is on the page). Insert this line at the very top of every file you edit: "> Ticks and notes in this file are SIMULATED (Sonnet 5.5 playing the operator, mode ${run.mode}), not the operator's input." followed by a blank line.
Then append to ${r.round_folder}/SIMULATED.md one line per file listing what you ticked, under the header "Simulated operator (Sonnet 5.5, mode ${run.mode}). Not the operator's input."
Return boxes ticked, words written in notes, and your verdict if the round holds an INTENT.md with a Confirm block (else not_an_intent_round).`
phase('Runs')
return await pipeline(args.runs, async (run) => {
  const log_ = []
  for (let i = 1; i <= CAP[run.p] + 3; i++) {
    const r = await agent(runnerPrompt(run), { label: `${run.id} r${i}`, phase: 'Runs', effort: 'high', schema: RUNNER })
    if (!r) { log_.push({ i, error: 'runner null' }); break }
    log_.push({ i, kind: r.kind, folder: r.round_folder, note: r.note.slice(0, 300) })
    if (r.kind === 'none' || !r.operator_files.length) break
    const s = await agent(simPrompt(run, r), { label: `${run.id} sim${i}`, phase: 'Runs', model: 'sonnet', effort: 'medium', schema: SIM })
    log_.push({ i, sim: s })
    if (s && r.kind === 'intent' && s.intent_verdict === 'yes') break
  }
  return { id: run.id, rounds: log_ }
})

