import json, os, re, sys

runs_dir = sys.argv[1]
out = {}
for run in sorted(os.listdir(runs_dir)):
    rd = os.path.join(runs_dir, run)
    if not os.path.isdir(rd):
        continue
    rounds = sorted(d for d in os.listdir(rd) if d.startswith("Round_"))
    words = ticks = note_words = 0
    intent_path, verdict = None, None
    for r in rounds:
        for f in sorted(os.listdir(os.path.join(rd, r))):
            if not f.endswith(".md") or f in ("ROUND.md", "SIMULATED.md"):
                continue
            t = open(os.path.join(rd, r, f), encoding="utf-8").read()
            words += len(re.findall(r"\w+", t))
            ticks += len(re.findall(r"- \[[xX]\]", t))
            for block in re.findall(r"```notes\n(.*?)```", t, re.S):
                note_words += len(re.findall(r"\w+", block))
            if f == "INTENT.md":
                intent_path = f"{r}/INTENT.md"
                if re.search(r"- \[[xX]\] Yes", t):
                    verdict = "yes"
                elif re.search(r"- \[[xX]\] Close", t):
                    verdict = "close"
                elif re.search(r"- \[[xX]\] No", t):
                    verdict = "no"
                else:
                    verdict = "unticked"
    out[run] = {"rounds": len(rounds), "words_shown": words, "ticks": ticks,
                "note_words": note_words, "final_intent": intent_path, "final_verdict": verdict}
json.dump(out, sys.stdout, indent=1)

